// Concatenates every migration into supabase/setup.sql so the whole schema can be
// pasted into the Supabase SQL editor in one go (alternative to `supabase db push`).
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

export function buildSetupSql(root = process.cwd()) {
  const dir = join(root, "supabase", "migrations");
  const files = readdirSync(dir).filter((f) => f.endsWith(".sql")).sort();
  const header =
    "-- FCA-AI database setup: all migrations in order. GENERATED by `npm run db:setup-sql` — do not edit.\n" +
    "-- Run once on a NEW Supabase project (SQL editor → paste → Run). For later changes use `supabase db push`.\n";
  return header + files.map((f) => `\n-- ===== ${f} =====\n` + readFileSync(join(dir, f), "utf8")).join("");
}

if (import.meta.url === `file://${process.argv[1]}`) {
  writeFileSync(join(process.cwd(), "supabase", "setup.sql"), buildSetupSql());
  console.log("Wrote supabase/setup.sql");
}
